{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "boxcutter",
  "description": "Boxcutter - ephemeral dev environment VMs powered by Firecracker microVMs",
  "owner": {
    "name": "Andrew Budd",
    "email": "andrewbudd@github.com"
  },
  "plugins": [
    {
      "name": "boxcutter",
      "description": "Manage ephemeral dev environment VMs using Boxcutter. Firecracker microVMs that boot in ~1 second with real LAN IPs and SSH access. Use when users need a fresh dev environment, want to test in a clean VM, need isolated compute, or mention Boxcutter.",
      "version": "1.0.0",
      "author": {
        "name": "Andrew Budd",
        "email": "andrewbudd@github.com"
      },
      "source": "./plugins/boxcutter",
      "category": "development"
    },
    {
      "name": "tapegun-host",
      "description": "Monitor and message Boxcutter VMs using the Tapegun system. For use by a Claude Code instance managing VMs from outside — check VM activity, send tasks, broadcast instructions.",
      "version": "1.1.0",
      "author": {
        "name": "Andrew Budd",
        "email": "andrewbudd@github.com"
      },
      "source": "./plugins/tapegun-host",
      "category": "development"
    },
    {
      "name": "tapegun-guest",
      "description": "Receive messages and tasks from external agents inside a Boxcutter VM. For use by a Claude Code instance running inside a VM — monitors inbox for incoming directives.",
      "version": "1.1.0",
      "author": {
        "name": "Andrew Budd",
        "email": "andrewbudd@github.com"
      },
      "source": "./plugins/tapegun-guest",
      "category": "development"
    }
  ]
}
